using System;using System.IO;using System.Reflection;using System.Xml;using MediaPortal.Common.Utils;using MediaPortal.GUI.Library;
[assembly: AssemblyVersion("1.0.0.0")][assembly: CompatibleVersion("1.39.0.0")]
namespace MP1SkinStudio.SpecialValidation{
 public sealed class SpecialScenePlugin:IPlugin,ISetupForm{
 System.Windows.Forms.Timer timer; SpecialWindow scene;string mode="small";
 public string PluginName(){return "Skin Studio Special Fixture";}public string Description(){return "Isolated special live test";}public string Author(){return "MP1 Skin Studio";}public bool CanEnable(){return true;}public bool DefaultEnabled(){return true;}public bool HasSetup(){return false;}public void ShowPlugin(){}public int GetWindowId(){return 0;}public bool GetHome(out string n,out string i,out string f,out string p){n=i=f=p="";return false;}
 public void Start(){scene=new SpecialWindow();if(!scene.Init())return;GUIWindow window=scene;GUIWindowManager.Add(ref window);timer=new System.Windows.Forms.Timer{Interval=250};timer.Tick+=(s,e)=>Observe();timer.Start();}public void Stop(){if(timer!=null)timer.Dispose();}
 void Observe(){try{string dir=Environment.GetEnvironmentVariable("MP1_SKIN_STUDIO_LIVE_DIR");if(String.IsNullOrEmpty(dir)||!scene.WindowLoaded||GUIWindowManager.ActiveWindowEx!=90120)return;var gallery=scene.GetControl(21204) as GUIThumbnailPanel;string command=Path.Combine(dir,"special-mode.txt");if(File.Exists(command)){string next=File.ReadAllText(command).Trim();if(next=="big"||next=="small"){gallery.ShowBigIcons(next=="big");mode=next;}File.Delete(command);}var doc=new XmlDocument();var root=doc.CreateElement("state");doc.AppendChild(root);root.SetAttribute("items",gallery.Count.ToString());root.SetAttribute("mode",mode);root.SetAttribute("tick",DateTime.UtcNow.Ticks.ToString());string path=Path.Combine(dir,"special-state.xml"),temp=path+".tmp";doc.Save(temp);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}catch(Exception ex){Log.Warn("Special fixture: {0}",ex.Message);}}
 }
 public sealed class SpecialWindow:GUIWindow{public SpecialWindow(){GetID=90120;}public override bool Init(){return Load(Path.Combine(GUIGraphicsContext.Skin,"studio.live.special.xml"));}protected override void OnPageLoad(){base.OnPageLoad();var gallery=GetControl(21204) as GUIThumbnailPanel;if(gallery.Count==0)for(int i=0;i<6;i++)gallery.Add(new GUIListItem("Gallery item "+(i+1)));gallery.ShowBigIcons(false);}}
}
